00067 const uint32_t kNalHeaderLength = 3;
00068 const uint8_t kNalHeader[kNalHeaderLength] = {0, 0, 1};
00069 const uint32_t kNalEscapeLength = 3;
00070 const uint8_t kNalEscape[kNalEscapeLength] = {0, 0, 3};
