00072 const uint8_t kMaxNumRefFramesAllowed = 16;
00073 
00074 uint32_t GetBitCountFromMax(uint32_t maxValue) {
00075     // Bit count is determined by ceil(log2(maxRepresentation);
00076     // Because log2 is c99 which is not so widely available we can use standard log with a divide.
00077     // log2(x) = logY(x) / logY(2)
00078     //
00079     // Alternatively we want to find the highest bit set in maxValue.
00080     static const float logBase = log(2.0f);
00081     float log2Value = log(static_cast<float>(maxValue)) / logBase;
00082     return static_cast<uint32_t>(ceil(log2Value));
00083 }
