00085 BaseDecNalUnitType::Enum uFromHEVC(uint8_t type) {
00086     switch (type) {
00087     case HEVCNalType::CodedSlice_Trail_N:
00088     case HEVCNalType::CodedSlice_Trail_R:
00089     case HEVCNalType::CodedSlice_TSA_N:
00090     case HEVCNalType::CodedSlice_TLA_R:
00091     case HEVCNalType::CodedSlice_STSA_N:
00092     case HEVCNalType::CodedSlice_STSA_R:
00093     case HEVCNalType::CodedSlice_RADL_N:
00094     case HEVCNalType::CodedSlice_RADL_R:
00095     case HEVCNalType::CodedSlice_RASL_N:
00096     case HEVCNalType::CodedSlice_RASL_R:
00097     case HEVCNalType::CodedSlice_BLA_W_LP:
00098     case HEVCNalType::CodedSlice_BLA_W_RADL:
00099     case HEVCNalType::CodedSlice_BLA_N_LP:
00100     case HEVCNalType::CodedSlice_IDR_W_RADL:
00101     case HEVCNalType::CodedSlice_IDR_N_LP:
00102     case HEVCNalType::CodedSlice_CRA:
00103         return BaseDecNalUnitType::Slice;
00104     case HEVCNalType::VPS:
00105         return BaseDecNalUnitType::VPS;
00106     case HEVCNalType::SPS:
00107         return BaseDecNalUnitType::SPS;
00108     case HEVCNalType::PPS:
00109         return BaseDecNalUnitType::PPS;
00110     case HEVCNalType::AUD:
00111         return BaseDecNalUnitType::AUD;
00112     case HEVCNalType::EndOfSequence:
00113         return BaseDecNalUnitType::EOS;
00114     case HEVCNalType::EndOfBitstream:
00115         return BaseDecNalUnitType::EOB;
00116     case HEVCNalType::FillerData:
00117         return BaseDecNalUnitType::Filler;
00118     case HEVCNalType::PrefixSEI:
00119     case HEVCNalType::SuffixSEI:
00120         return BaseDecNalUnitType::SEI;
00121     }
00122 
00123     return BaseDecNalUnitType::Unknown;
00124 }
