00126 uint32_t uOffsetForNalUnitHeader(const uint8_t *nal) {
00127     if (memcmp(nal, kNalHeader, kNalHeaderLength) == 0)
00128         return kNalHeaderLength;
00129     if (!nal[0] && memcmp(nal + 1, kNalHeader, kNalHeaderLength) == 0)
00130         return kNalHeaderLength + 1;
00131     return 0;
00132 }
