00149 bool BaseDecoderHEVC::ParseNalUnit(const uint8_t *nal, uint32_t nalLength) {
00150     bool bSuccess = true;
00151 
00152     // Account for AnnexB nal unit header ([0],0,0,1)
00153     uint32_t offset = uOffsetForNalUnitHeader(nal);
00154 
00155     // [forbidden-zero:1, nal_type:6, layer_id_top:1]
00156     m_currentNalType = ((nal[offset] >> 1) & 0x3F);
00157     // [layer_id:5, temporal_id_plus1:3]
00158     m_currentTemporalId = nal[offset + 1] >> 5;
00159 
00160     offset += 2;
00161 
00162     BaseDecNalUnitType::Enum nalType = uFromHEVC(m_currentNalType);
00163 
00164     // if (nalType != BaseDecNalUnitType::VPS)
00165     {
00166         // printf("BaseDecoderHEVC::ParseNalUnit [%d] --> [%s] nallenght [%d]\n", m_currentNalType, uToString(nalType),
00167         // nalLengthIn);
00168         nal += offset;
00169         nalLength -= offset;
00170 
00171         Unencapsulate(nal, nalLength, m_currentNalPayload);
00172         m_currentBits = *m_currentNalPayload.data();
00173         m_remainingBits = 8;
00174         m_byteOffset = 0;
00175 
00176         switch (nalType) {
00177         case BaseDecNalUnitType::VPS:
00178             bSuccess = ParseVPS();
00179             break;
00180         case BaseDecNalUnitType::PPS:
00181             bSuccess = ParsePPS();
00182             break;
00183         case BaseDecNalUnitType::SPS:
00184             bSuccess = ParseSPS();
00185             break;
00186         case BaseDecNalUnitType::Slice:
00187             if ((bSuccess = ParseSliceHeader())) {
00188                 HandleSliceHeader();
00189                 HandlePictureOrderCount();
00190                 m_bFirstPicture = false;
00191             }
00192             break;
00193         case BaseDecNalUnitType::EOS:
00194             m_bFirstPicture = true;
00195             break;
00196         default:
00197             break;
00198         }
00199     }
00200     // else
00201     //    printf("BaseDecoderHEVC::ParseNalUnit [%d] --> [%s] nallenght [%d] ---->> SKIPPED\n", m_currentNalType,
00202     //    uToString(nalType), nalLengthIn);
00203 
00204     return bSuccess;
00205 }
