00230 uint32_t BaseDecoderHEVC::GetPictureWidth() const {
00231     if (!m_activeSPS) {
00232         return 0;
00233     }
00234 
00235     // 6.2
00236     uint32_t subWidthC = 1;
00237     if (m_activeSPS->m_chromaFormatIDC == 1 || m_activeSPS->m_chromaFormatIDC == 2) {
00238         subWidthC = 2;
00239     }
00240 
00241     return m_activeSPS->m_picWidthInLumaSamples -
00242            subWidthC * (m_activeSPS->m_confWinRightOffset + m_activeSPS->m_confWinLeftOffset); // (D-28)
00243 }
00244 
00245 uint32_t BaseDecoderHEVC::GetPictureHeight() const {
00246     if (!m_activeSPS) {
