00253         subHeightC = 2;
00254     }
00255 
00256     return m_activeSPS->m_picHeightInLumaSamples -
00257            subHeightC * (m_activeSPS->m_confWinBottomOffset + m_activeSPS->m_confWinTopOffset); // (D-29)
