00302 // Section 8.3.1 of Standard
00303 void BaseDecoderHEVC::HandlePictureOrderCount() {
00304     uint32_t picOrderCntMsb = 0;
00305     uint32_t maxPicOrderCntLsb = 1 << m_activeSPS->m_log2MaxPicOrderCntLSB;
00306     HEVCNalType::Enum nalType = static_cast<HEVCNalType::Enum>(m_currentNalType);
00307 
00308     if (isIdr(nalType)) {
00309         // Note 1
00310         m_prevTid0Pic.m_picOrderCntLsb = 0;
00311         m_prevTid0Pic.m_picOrderCntMsb = 0;
00312         m_activeSlice.m_slicePicOrderCntLSB = 0;
00313     }
00314 
00315     uint32_t prevPicOrderCntLsb = m_prevTid0Pic.m_picOrderCntLsb;
00316     uint32_t prevPicOrderCntMsb = m_prevTid0Pic.m_picOrderCntMsb;
00317 
00318     // (8-1)
00319     if (isIrap(nalType) && m_bNoRaslOutput) {
00320         picOrderCntMsb = 0;
00321     } else if (m_activeSlice.m_slicePicOrderCntLSB < prevPicOrderCntLsb &&
00322                (prevPicOrderCntLsb - m_activeSlice.m_slicePicOrderCntLSB) >= (maxPicOrderCntLsb / 2)) {
00323         picOrderCntMsb = prevPicOrderCntMsb + maxPicOrderCntLsb;
00324     } else if (m_activeSlice.m_slicePicOrderCntLSB > prevPicOrderCntLsb &&
00325                (m_activeSlice.m_slicePicOrderCntLSB - prevPicOrderCntLsb) > (maxPicOrderCntLsb / 2)) {
00326         picOrderCntMsb = prevPicOrderCntMsb - maxPicOrderCntLsb;
00327     } else
00328         picOrderCntMsb = prevPicOrderCntMsb;
00329 
00330     if (!isRasl(nalType) && !isRadl(nalType) && !isSubLayerNonReferencePicture(nalType) && m_currentTemporalId == 0) {
00331         m_prevTid0Pic.m_picOrderCntLsb = m_activeSlice.m_slicePicOrderCntLSB;
00332         m_prevTid0Pic.m_picOrderCntMsb = picOrderCntMsb;
00333     }
00334 
00335     // (8-2)
00336     m_currentPictureOrderCount = picOrderCntMsb + m_activeSlice.m_slicePicOrderCntLSB;
00337 }
