00339 // Section 7.4.2.2 of Standard
00340 bool BaseDecoderHEVC::isSubLayerNonReferencePicture(HEVCNalType::Enum nut) {
00341     switch (nut) {
00342     case HEVCNalType::CodedSlice_Trail_N:
00343     case HEVCNalType::CodedSlice_TSA_N:
00344     case HEVCNalType::CodedSlice_STSA_N:
00345     case HEVCNalType::CodedSlice_RADL_N:
00346     case HEVCNalType::CodedSlice_RASL_N:
00347     case HEVCNalType::RSV_VCL_N10:
00348     case HEVCNalType::RSV_VCL_N12:
00349     case HEVCNalType::RSV_VCL_N14:
00350         return true;
00351     default:
00352         return false;
00353     }
00354 }
