00410 bool BaseDecoderHEVC::ParseSPS() {
00411     uint32_t vpsID = ReadBits(4);
00412     // REPORT("%-40s - %8d", "sps_video_parameter_set_id", vpsID);
00413     uint32_t maxSubLayersMinus1 = ReadBits(3);
00414     // REPORT("%-40s - %8d", "sps_max_sub_layers_minus1", maxSubLayersMinus1);
00415     bool bTemporalIDNesting = ReadFlag();
00416     // REPORT("%-40s - %8d", "sps_temporal_id_nesting_flag", bTemporalIDNesting);
00417 
00418     if (!ParseProfileTierLevels(true, maxSubLayersMinus1)) {
00419         return false;
00420     }
00421 
00422     uint32_t spsID = ReadUE();
00423     // REPORT("%-40s - %8d", "sps_seq_parameter_set_id", spsID);
00424 
00425     if (spsID >= HEVCMaxSPSCount) {
00426         INFO("spsID out of range %4d", spsID);
00427         throw std::runtime_error("spsID out of range");
00428         return false;
00429     }
00430 
00431     m_activeSPS = &m_sps[spsID];
00432     m_activeSPS->m_vpsID = vpsID;
00433     m_activeSPS->m_maxSubLayers = maxSubLayersMinus1 + 1;
00434     m_activeSPS->m_bTemporalIDNesting = bTemporalIDNesting;
00435     m_activeSPS->m_spsID = spsID;
00436     m_activeSPS->m_chromaFormatIDC = ReadUE();
00437     // REPORT("%-40s - %8d", "chroma_format_idc", m_activeSPS->m_chromaFormatIDC);
00438 
00439     if (m_activeSPS->m_chromaFormatIDC == 3) {
00440         m_activeSPS->m_bSeparateColourPlane = ReadFlag();
00441     }
00442 
00443     if (m_activeSPS->m_bSeparateColourPlane == false) {
00444         m_activeSPS->m_chromaArrayType = m_activeSPS->m_chromaFormatIDC;
00445     } else {
00446         m_activeSPS->m_chromaArrayType = 0;
00447     }
00448 
00449     m_activeSPS->m_picWidthInLumaSamples = ReadUE();
00450     // REPORT("%-40s - %8d", "pic_width_in_luma_samples", m_activeSPS->m_picWidthInLumaSamples);
00451     m_activeSPS->m_picHeightInLumaSamples = ReadUE();
00452     // REPORT("%-40s - %8d", "pic_height_in_luma_samples", m_activeSPS->m_picHeightInLumaSamples);
00453     m_activeSPS->m_bConformanceWindow = ReadFlag();
00454     // REPORT("%-40s - %8d", "conformance_window_flag", m_activeSPS->m_bConformanceWindow);
00455 
00456     if (m_activeSPS->m_bConformanceWindow) {
00457         m_activeSPS->m_confWinLeftOffset = ReadUE();
00458         m_activeSPS->m_confWinRightOffset = ReadUE();
00459         m_activeSPS->m_confWinTopOffset = ReadUE();
00460         m_activeSPS->m_confWinBottomOffset = ReadUE();
00461     }
00462 
00463     m_activeSPS->m_bitDepthLuma = ReadUE() + 8;
00464     m_activeSPS->m_bitDepthChroma = ReadUE() + 8;
00465     m_activeSPS->m_log2MaxPicOrderCntLSB = ReadUE() + 4;
00466     // REPORT("%-40s - %8d", "log2_max_pic_order_cnt_lsb_minus4", m_activeSPS->m_log2MaxPicOrderCntLSB - 4);
00467 
00468     m_activeSPS->m_bSubLayerOrderingInfoPresent = ReadFlag();
00469     // REPORT("%-40s - %8d", "sps_sub_layer_ordering_info_present_flag", m_activeSPS->m_bSubLayerOrderingInfoPresent);
00470 
00471     for (uint32_t i = (m_activeSPS->m_bSubLayerOrderingInfoPresent ? 0 : maxSubLayersMinus1); i <= maxSubLayersMinus1; ++i) {
00472         int sps_max_dec_pic_buffering_minus1 = ReadUE(); // max_dec_pic_buffering_minus1
00473         // REPORT("%-40s - %8d - %8d", "sps_max_dec_pic_buffering_minus1", i, sps_max_dec_pic_buffering_minus1);
00474         m_activeSPS->m_maxNumReorderPics[i] = ReadUE();
00475         // REPORT("%-40s - %8d - %8d", "sps_max_num_reorder_pics", i, m_activeSPS->m_maxNumReorderPics[i]);
00476         int max_latency_increase_plus1 = ReadUE(); // max_latency_increase_plus1
00477         // REPORT("%-40s - %8d - %8d", "max_latency_increase_plus1", i, max_latency_increase_plus1);
00478     }
00479 
00480     m_activeSPS->m_log2MinLumaCodingBlockSize = ReadUE() + 3;
00481     m_activeSPS->m_log2DiffMaxMinLumaCodingBlockSize = ReadUE();
00482     m_activeSPS->m_log2MinLumaTransformBlockSize = ReadUE() + 2;
00483     m_activeSPS->m_log2DiffMaxMinLumaTransformBlockSize = ReadUE();
00484     m_activeSPS->m_maxTransformHierarchyDepthInter = ReadUE();
00485     // REPORT("%-40s - %8d", "max_transform_hierarchy_depth_inter", m_activeSPS->m_maxTransformHierarchyDepthInter);
00486     m_activeSPS->m_maxTransformHierarchyDepthIntra = ReadUE();
00487     // REPORT("%-40s - %8d", "max_transform_hierarchy_depth_intra", m_activeSPS->m_maxTransformHierarchyDepthIntra);
00488     m_activeSPS->m_bScalingListEnabled = ReadFlag();
00489     // REPORT("%-40s - %8d", "scaling_list_enabled_flag", m_activeSPS->m_bScalingListEnabled);
00490 
00491     if (m_activeSPS->m_bScalingListEnabled) {
00492         m_activeSPS->m_bScalingListDataPresent = ReadFlag();
00493 
00494         if (m_activeSPS->m_bScalingListDataPresent) {
00495             // todo!
00496             BaseDecoderHEVC::HandleScalingList();
00497             // throw std::runtime_error("Unimplemented HEVC header parsing [scaling list]\n");
00498         }
00499     }
00500 
00501     m_activeSPS->m_bAMPEnabled = ReadFlag();
00502     m_activeSPS->m_bSampleAdaptiveOffsetEnabled = ReadFlag();
00503     m_activeSPS->m_bPCMEnabled = ReadFlag();
00504 
00505     if (m_activeSPS->m_bPCMEnabled) {
00506         m_activeSPS->m_pcmSampleBitDepthLuma = ReadBits(4) + 1;
00507         m_activeSPS->m_pcmSampleBitDepthChroma = ReadBits(4) + 1;
00508         m_activeSPS->m_log2MinPCMLumaCodingBlockSize = ReadUE() + 3;
00509         m_activeSPS->m_log2DiffMaxMinPCMLumaCodingBlockSize = ReadUE();
00510         m_activeSPS->m_bPCMLoopFilterDisabled = ReadFlag();
00511     }
00512 
00513     m_activeSPS->m_numShortTermRefPicSets = ReadUE();
00514     // REPORT("%-40s - %8d", "num_short_term_ref_pic_sets", m_activeSPS->m_numShortTermRefPicSets);
00515 
00516     // debug0879
00517     // Ignore remaining data for now.
00518     return true;
00519 
00520     for (uint32_t i = 0; i < m_activeSPS->m_numShortTermRefPicSets; ++i) {
00521         ParseShortTermRefSet(i);
00522         // printf("Unimplemented HEVC header pasing [short term ref pic sets]\n");
00523         // throw std::runtime_error("Unimplemented HEVC header pasing [short term ref pic sets]\n");
00524     }
00525 
00526     m_activeSPS->m_bLongTermRefPicsPresent = ReadFlag();
00527 
00528     if (m_activeSPS->m_bLongTermRefPicsPresent) {
00529         m_activeSPS->m_numLongTermRefPics = ReadUE();
00530 
00531         for (uint32_t i = 0; i < m_activeSPS->m_numLongTermRefPics; ++i) {
00532             m_activeSPS->m_longTermRefPicPOCLSB[i] = ReadBits(m_activeSPS->m_log2MaxPicOrderCntLSB);
00533             m_activeSPS->m_bLongTermUsedByCurrentPic[i] = ReadFlag();
00534         }
00535     }
00536 
00537     m_activeSPS->m_bTemporalMVPEnabled = ReadFlag();
00538     m_activeSPS->m_bStrongIntraSmoothingEnabled = ReadFlag();
00539 #if !defined(NO_VUIPARAMS)
00540     if ((m_activeSPS->m_bVUIParametersPresent = ReadFlag())) {
00541         HandleVUIParameters(); // Doesn't parse entire VUI
00542     }
00543 #endif
00544 
00545     // Ignore remaining data for now.
00546     return true;
00547 }
