00549 bool BaseDecoderHEVC::ParsePPS() {
00550     uint32_t ppsID = ReadUE();
00551 
00552     if (ppsID >= HEVCMaxPPSCount) {
00553         INFO("ppsID out of range %4d", ppsID);
00554         throw std::runtime_error("ppsID out of range");
00555         return false;
00556     }
00557 
00558     m_activePPS = &m_pps[ppsID];
00559     m_activePPS->m_ppsID = ppsID;
00560     m_activePPS->m_spsID = ReadUE();
00561     m_activePPS->m_bDependentSliceSegmentsEnabled = ReadFlag();
00562     m_activePPS->m_bOutputFlagPresent = ReadFlag();
00563     m_activePPS->m_numExtraSliceHeaderBits = ReadBits(3);
00564     m_activePPS->m_bSignDataHidingEnabled = ReadFlag();
00565     m_activePPS->m_bCabacInitPresent = ReadFlag();
00566     m_activePPS->m_numRefIDXL0Active = ReadUE() + 1;
00567     m_activePPS->m_numRefIDXL1Active = ReadUE() + 1;
00568     m_activePPS->m_initQP = ReadSE() + 26;
00569     m_activePPS->m_bConstrainedIntraPred = ReadFlag();
00570     m_activePPS->m_bTransformSkipEnabled = ReadFlag();
00571     m_activePPS->m_bCUQPDeltaEnabled = ReadFlag();
00572 
00573     if (m_activePPS->m_bCUQPDeltaEnabled) {
00574         m_activePPS->m_diffCUQPDeltaDepth = ReadUE();
00575     }
00576 
00577     m_activePPS->m_cbqpOffset = ReadSE();
00578     m_activePPS->m_crqpOffset = ReadSE();
00579     m_activePPS->m_bSliceChromaQPOffsetsPresent = ReadFlag();
00580     m_activePPS->m_bWeightedPred = ReadFlag();
00581     m_activePPS->m_bWeightedBipred = ReadFlag();
00582     m_activePPS->m_bTransquantBypassEnabled = ReadFlag();
00583     m_activePPS->m_bTilesEnabled = ReadFlag();
00584     m_activePPS->m_bEntropyCodingSyncEnabled = ReadFlag();
00585 
00586     if (m_activePPS->m_bTilesEnabled) {
00587         INFO("Unimplemented HEVC header parsing [tiles enabled]");
00588         throw std::runtime_error("Unimplemented HEVC header parsing [tiles enabled]");
00589     }
00590 
00591     m_activePPS->m_bPPSLoopFilterAcrossSlicesEnabled = ReadFlag();
00592     m_activePPS->m_bDeblockingFilterControlPresent = ReadFlag();
00593 
00594     if (m_activePPS->m_bDeblockingFilterControlPresent) {
00595         m_activePPS->m_bDeblockingFilterOverrideEnabled = ReadFlag();
00596         m_activePPS->m_bPPSDeblockingFilterDisabled = ReadFlag();
00597 
00598         if (!m_activePPS->m_bPPSDeblockingFilterDisabled) {
00599             m_activePPS->m_ppsBetaOffsetDiv2 = ReadSE();
00600             m_activePPS->m_ppsTCOffsetDiv2 = ReadSE();
00601         }
00602     }
00603 
00604     m_activePPS->m_bPPSScalingListDataPresent = ReadFlag();
00605 
00606     if (m_activePPS->m_bPPSScalingListDataPresent) {
00607         for (uint8_t sizeId = 0; sizeId < 4; ++sizeId) {
00608             for (uint8_t matrixId = 0; matrixId < 6; matrixId += (sizeId == 3 ? 3 : 1)) {
00609                 bool scalingListPredMode = ReadFlag(); // scaling_list_pred_mode_flag[sizeId][matrixId]
00610 
00611                 if (!scalingListPredMode)
00612                     ReadUE(); // scaling_list_pred_matrix_id_delta[sizeId][matrixId]
00613                 else {
00614                     int32_t nextCoef = 8;
00615                     uint32_t coefNum = std::min(64, (1 << (4 + (sizeId << 1))));
00616 
00617                     if (sizeId > 1)
00618                         nextCoef = ReadSE() + 8; // scaling_list_dc_coef_minus8[sizeId - 2][matrixId]
00619 
00620                     for (uint32_t i = 0; i < coefNum; ++i)
00621                         ReadSE(); // scaling_list_delta_coef
00622                 }
00623             }
00624         }
00625     }
00626 
00627     m_activePPS->m_bListsModificationPresent = ReadFlag();
00628     m_activePPS->m_log2ParallelMergeLevelMinus2 = ReadUE();
00629     m_activePPS->m_bSliceSegmentHeaderExtensionPresent = ReadFlag();
00630 
00631     return true;
00632 }
