00634 bool BaseDecoderHEVC::ParseSliceHeader() {
00635     m_activeSlice.m_bFirstSliceSegmentInPic = ReadFlag();
00636 
00637     if (m_currentNalType >= 16 && m_currentNalType <= 23) {
00638         m_activeSlice.m_bNoOutputOfPriorPics = ReadFlag();
00639     }
00640 
00641     m_activeSlice.m_ppsID = ReadUE();
00642     m_activeSlice.m_pps = &m_pps[m_activeSlice.m_ppsID];
00643     m_activeSlice.m_sps = &m_sps[m_activeSlice.m_pps->m_spsID];
00644 
00645     if (!m_activeSlice.m_bFirstSliceSegmentInPic) {
00646         if (m_activeSlice.m_pps->m_bDependentSliceSegmentsEnabled) {
00647             m_activeSlice.m_bDependentSliceSegment = ReadFlag();
00648         }
00649 
00650         // @todo
00651         m_activeSlice.m_sliceSegmentAddress = 0;
00652         INFO("Unimplemented HEVC header parsing [first slice segment in pic]");
00653         throw std::runtime_error("Unimplemented HEVC header parsing [first slice segment in pic]\n");
00654     }
00655 
00656     if (!m_activeSlice.m_pps->m_bDependentSliceSegmentsEnabled) {
00657         for (uint32_t i = 0; i < m_activeSlice.m_pps->m_numExtraSliceHeaderBits; ++i) {
00658             ReadFlag(); // slice_reserved_flag[ i ]
00659         }
00660 
00661         m_activeSlice.m_sliceType = ReadUE();
00662 
00663         if (m_activeSlice.m_pps->m_bOutputFlagPresent) {
00664             m_activeSlice.m_bPicOutput = ReadFlag();
00665         }
00666 
00667         if (m_activeSlice.m_sps->m_bSeparateColourPlane) {
00668             m_activeSlice.m_colourPlaneID = ReadBits(2);
00669         }
00670 
00671         if (m_currentNalType != 19 && m_currentNalType != 20) {
00672             m_activeSlice.m_slicePicOrderCntLSB = ReadBits(m_activeSlice.m_sps->m_log2MaxPicOrderCntLSB);
00673             bool bShortTermRefPicSetSPS = ReadFlag(); // short_term_ref_pic_set_sps_flag
00674 #if !defined(NO_STRPS)
00675             if (!bShortTermRefPicSetSPS) {
00676                 ParseShortTermRefSet(m_activeSlice.m_sps->m_numShortTermRefPicSets);
00677             } else if (m_activeSlice.m_sps->m_numShortTermRefPicSets > 1) {
00678                 m_activeSlice.m_shortTermRefPicIdx = ReadBits(GetBitCountFromMax(m_activeSlice.m_sps->m_numShortTermRefPicSets));
00679             }
00680 
00681             if (m_activeSlice.m_sps->m_bLongTermRefPicsPresent) {
00682                 if (m_activeSlice.m_sps->m_numLongTermRefPics > 0) {
00683                     m_activeSlice.m_numLongTermSPS = ReadUE();
00684                 }
00685 
00686                 m_activeSlice.m_numLongTermPics = ReadUE();
00687 
00688                 for (uint32_t i = 0; i < (m_activeSlice.m_numLongTermSPS + m_activeSlice.m_numLongTermPics); ++i) {
00689                     if (i < m_activeSlice.m_numLongTermSPS) {
00690                         if (m_activeSlice.m_sps->m_numLongTermRefPics > 1) {
00691                             ReadBits(GetBitCountFromMax(m_activeSlice.m_sps->m_numLongTermRefPics)); // lt_idx_sps[i]
00692                         }
00693                     } else {
00694                         ReadBits(GetBitCountFromMax(m_activeSlice.m_sps->m_log2MaxPicOrderCntLSB)); // poc_lsb_lt[i]
00695                         ReadFlag();                                                                 // used_by_curr_pic_lt_flag[i]
00696                     }
00697 
00698                     if (ReadFlag()) // delta_poc_msb_present[i]
00699                     {
00700                         ReadUE(); // delta_poc_msb_cycle_lt[i]
00701                     }
00702                 }
00703             }
00704 
00705             if (m_activeSlice.m_sps->m_bTemporalMVPEnabled) {
00706                 ReadFlag(); // slice_temporal_mvp_enabled
00707             }
00708 #endif
00709         }
00710 #if !defined(NO_STRPS) // Out of sync - ignore
00711         if (m_activeSlice.m_sps->m_bSampleAdaptiveOffsetEnabled) {
00712             m_activeSlice.m_bSliceSAOLuma = ReadFlag();
00713 
00714             if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
00715                 m_activeSlice.m_bSliceSAOChroma = ReadFlag();
00716             }
00717         }
00718 
00719         if ((m_activeSlice.m_sliceType == SliceType::P) || (m_activeSlice.m_sliceType == SliceType::B)) {
00720             m_activeSlice.m_bNumRefIdxActiveOverride = ReadFlag();
00721 
00722             if (m_activeSlice.m_bNumRefIdxActiveOverride) {
00723                 m_activeSlice.m_numRefIDXL0ActiveMinus1 = ReadUE();
00724 
00725                 if (m_activeSlice.m_sliceType == SliceType::B) {
00726                     m_activeSlice.m_numRefIDXL1ActiveMinus1 = ReadUE();
00727                 }
00728             }
00729 
00730             if (m_activeSlice.m_pps->m_bListsModificationPresent /*&& (NumPicTotalCurr > 1)*/) {
00731                 ParseRefPicListsModification();
00732             }
00733 
00734             if (m_activeSlice.m_sliceType == SliceType::B) {
00735                 m_activeSlice.m_bMVDL1Zero = ReadFlag();
00736             }
00737 
00738             if (m_activeSlice.m_pps->m_bCabacInitPresent) {
00739                 m_activeSlice.m_bCabacInit = ReadFlag();
00740             }
00741 
00742             if (m_activeSlice.m_sps->m_bTemporalMVPEnabled) {
00743                 if (m_activeSlice.m_sliceType == SliceType::B) {
00744                     m_activeSlice.m_bCollocatedFromL0 = ReadFlag();
00745                 }
00746 
00747                 if ((m_activeSlice.m_bCollocatedFromL0 && m_activeSlice.m_numRefIDXL0ActiveMinus1 > 0) ||
00748                     (!m_activeSlice.m_bCollocatedFromL0 && m_activeSlice.m_numRefIDXL1ActiveMinus1 > 0)) {
00749                     m_activeSlice.m_collocatedRefIdx = ReadUE();
00750                 }
00751             }
00752 
00753             if ((m_activeSlice.m_pps->m_bWeightedPred && (m_activeSlice.m_sliceType == SliceType::P)) ||
00754                 (m_activeSlice.m_pps->m_bWeightedBipred && (m_activeSlice.m_sliceType == SliceType::B))) {
00755                 ParsePredWeightTable();
00756             }
00757 
00758             m_activeSlice.m_fiveMinusMaxNumMergeCand = ReadUE();
00759         }
00760 
00761         m_activeSlice.m_sliceQPDelta = ReadSE();
00762         // m_activePPS->m_initQP += m_activeSlice.m_sliceQPDelta;   //  Modifies per-slice.
00763 #endif
00764     }
00765     return true;
00766 }
