00768 void BaseDecoderHEVC::HandleVUIParameters() {
00769     if (ReadFlag()) // aspect_ratio_info_present_flag
00770     {
00771         if (ReadBits(8) == 255) // aspect_ratio_idc == Extended_SAR
00772         {
00773             ReadBits(16); // sar_width
00774             ReadBits(16); // sar_height
00775         }
00776     }
00777 
00778     if (ReadFlag()) // overscan_info_present_flag
00779     {
00780         ReadFlag(); // overscan_appropriate_flag
00781     }
00782 
00783     if (ReadFlag()) // video_signal_type_present_flag
00784     {
00785         ReadBits(3);    // video_format
00786         ReadFlag();     // video_full_range_flag
00787         if (ReadFlag()) // colour_description_present_flag
00788         {
00789             ReadBits(8); // colour_primaries
00790             ReadBits(8); // transfer_characteristics
00791             ReadBits(8); // matrix_coefficients
00792         }
00793     }
00794     if (ReadFlag()) // chroma_loc_info_present_flag
00795     {
00796         ReadUE(); // chroma_sample_loc_type_top_field
00797         ReadUE(); // chroma_sample_loc_type_bottom_field
00798     }
00799     ReadFlag(); // neutral_chroma_indication_flag
00800     ReadFlag(); // field_seq_flag
00801     ReadFlag(); // frame_field_info_present_flag
00802 
00803     if (ReadFlag()) // default_display_window_flag
00804     {
00805         ReadUE(); // def_disp_win_left_offset
00806         ReadUE(); // def_disp_win_right_offset
00807         ReadUE(); // def_disp_win_top_offset
00808         ReadUE(); // def_disp_win_bottom_offset
00809     }
00810     if ((m_activeSPS->m_vui.m_bTimingInfoPresent = ReadFlag())) {
00811         m_activeSPS->m_vui.m_numUnitsInTick = ReadBits(32);
00812         m_activeSPS->m_vui.m_timeScale = ReadBits(32);
00813         // Ignore remaining data for now
00814     }
00815 }
