00817 bool BaseDecoderHEVC::ParseProfileTierLevels(bool bProfilePresent, uint32_t maxNumSubLayersMinus1) {
00818     if (bProfilePresent)
00819         ParseProfileTierLevel(true); // General Profile
00820 
00821     std::vector<bool> subLayerProfilePresent(maxNumSubLayersMinus1);
00822     std::vector<bool> subLayerLevelPresent(maxNumSubLayersMinus1);
00823 
00824     for (uint32_t i = 0; i < maxNumSubLayersMinus1; ++i) {
00825         subLayerProfilePresent[i] = ReadFlag();
00826         // REPORT("%-40s - %8d - %8d", "sub_layer_profile_present_flag", i, (bool)(subLayerProfilePresent[i]));
00827         subLayerLevelPresent[i] = ReadFlag();
00828         // REPORT("%-40s - %8d - %8d", "sub_layer_level_present_flag", i, (bool)(subLayerLevelPresent[i]));
00829     }
00830 
00831     if (maxNumSubLayersMinus1 > 0) {
00832         for (uint32_t i = maxNumSubLayersMinus1; i < 8; ++i)
00833             ReadBits(2); // reserved_zero_2bits
00834 
00835         for (uint32_t i = 0; i < maxNumSubLayersMinus1; ++i) {
00836             if (subLayerProfilePresent[i])
00837                 ParseProfileTierLevel(subLayerLevelPresent[i]); // sublayer[i] profile
00838         }
00839     }
00840 
00841     return true;
00842 }
