00857 
00858     bool bProgressiveSource = ReadFlag();
00859     // REPORT("%-40s - %8d", "general_progressive_source_flag", bProgressiveSource);
00860     bool bInterlacedSource = ReadFlag();
00861     // REPORT("%-40s - %8d", "general_interlaced_source_flag", bInterlacedSource);
00862     bool bNonPackedConstraint = ReadFlag();
00863     // REPORT("%-40s - %8d", "general_non_packed_constraint_flag", bNonPackedConstraint);
00864     bool bFrameOnlyConstraint = ReadFlag();
00865     // REPORT("%-40s - %8d", "general_frame_only_constraint_flag", bFrameOnlyConstraint);
00866 
00867     uint32_t reserved44Top = ReadBits(32);
00868     uint32_t reserved44Bottom = ReadBits(12);
00869 
00870     if (bLevelPresent) {
