00877 
00878 bool BaseDecoderHEVC::ParseShortTermRefSet(uint32_t idx) {
00879     bool bInterRefPicSetPrediction = false;
00880 
00881     if (idx != 0) {
00882         bInterRefPicSetPrediction = ReadFlag();
00883         // REPORT("%-40s - %8d", "inter_ref_pic_set_prediction_flag", bInterRefPicSetPrediction);
00884     }
00885 
00886     uint32_t deltaIdxMinus1 = 0;
00887     if (bInterRefPicSetPrediction) {
00888         // printf("Unimplemented HEVC header parsing [short-term ref]");
00889         // throw std::runtime_error("Unimplemented HEVC header parsing [short-term ref]");
00890 
00891         // printf("ParseShortTermRefSet:[%d] (bInterRefPicSetPrediction)\n", idx);
00892 
00893         if (idx == m_activeSPS->m_numShortTermRefPicSets) {
00894             deltaIdxMinus1 = ReadUE(); // delta_idx_minus1
00895         }
00896 
00897         uint32_t delta_rps_sign = ReadBits(1); // delta_rps_sign
00898         // REPORT("%-40s - %8d", "delta_rps_sign", delta_rps_sign);
00899         uint32_t abs_delta_rps_minus1 = ReadUE(); // abs_delta_rps_minus1
00900         // REPORT("%-40s - %8d", "abs_delta_rps_minus1", abs_delta_rps_minus1);
00901 
00902         uint32_t RefRpsIdx = idx - (deltaIdxMinus1 + 1);
00903         int32_t deltaRps = (1 - 2 * delta_rps_sign) * (abs_delta_rps_minus1 + 1);
00904 
00905         bool use_delta_flag[32] = {true};
00906 
00907         // REPORT("**** %4d **** %4d ****", deltaRps, m_activeSPS->m_NumDeltaPocs[RefRpsIdx]);
00908 
00909         for (uint32_t j = 0; j <= m_activeSPS->m_NumDeltaPocs[RefRpsIdx]; ++j) {
00910             m_activeSPS->m_used_by_curr_pic_flag[j] = ReadFlag();
00911             // REPORT("%-40s - %8d", "used_by_curr_pic_flag", m_activeSPS->m_used_by_curr_pic_flag[j]);
00912             if (!m_activeSPS->m_used_by_curr_pic_flag[j]) {
00913                 use_delta_flag[j] = ReadFlag();
00914                 // REPORT("%-40s - %8d", "use_delta_flag", use_delta_flag[j]);
00915             }
00916         }
00917 
00918         uint32_t u = 0;
00919         for (int32_t j = m_activeSPS->m_numPositivePics[RefRpsIdx] - 1; j >= 0; j--) {
00920             int32_t dpoc = m_activeSPS->m_DeltaPocS1[RefRpsIdx][j] + deltaRps;
00921             uint32_t kdx = m_activeSPS->m_numNegativePics[RefRpsIdx] + j;
00922             if (dpoc < 0 && use_delta_flag[kdx]) {
00923                 m_activeSPS->m_DeltaPocS0[idx][u] = dpoc;
00924                 m_activeSPS->m_UsedByCurrPicS0[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[kdx];
00925                 u++;
00926             }
00927         }
00928         uint32_t fdx = m_activeSPS->m_NumDeltaPocs[RefRpsIdx];
00929         if (deltaRps < 0 && use_delta_flag[fdx]) {
00930             m_activeSPS->m_DeltaPocS0[idx][u] = deltaRps;
00931             m_activeSPS->m_UsedByCurrPicS0[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[fdx];
00932             u++;
00933         }
00934         for (uint32_t j = 0; j < m_activeSPS->m_numNegativePics[RefRpsIdx]; ++j) {
00935             int32_t dpoc = m_activeSPS->m_DeltaPocS0[RefRpsIdx][j] + deltaRps;
00936             if (dpoc < 0 && use_delta_flag[j]) {
00937                 m_activeSPS->m_DeltaPocS0[idx][u] = dpoc;
00938                 m_activeSPS->m_UsedByCurrPicS0[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[j];
00939                 u++;
00940             }
00941         }
00942         m_activeSPS->m_numNegativePics[idx] = u;
00943         //==========================================================================================
00944         u = 0;
00945         for (int32_t j = m_activeSPS->m_numNegativePics[RefRpsIdx] - 1; j >= 0; j--) {
00946             int32_t dpoc = m_activeSPS->m_DeltaPocS0[RefRpsIdx][j] + deltaRps;
00947             if (dpoc > 0 && use_delta_flag[j]) {
00948                 m_activeSPS->m_DeltaPocS1[idx][u] = dpoc;
00949                 m_activeSPS->m_UsedByCurrPicS1[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[j];
00950                 u++;
00951             }
00952         }
00953         fdx = m_activeSPS->m_NumDeltaPocs[RefRpsIdx];
00954         if (deltaRps > 0 && use_delta_flag[fdx]) {
00955             m_activeSPS->m_DeltaPocS1[idx][u] = deltaRps;
00956             m_activeSPS->m_UsedByCurrPicS1[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[fdx];
00957             u++;
00958         }
00959         for (uint32_t j = 0; j < m_activeSPS->m_numPositivePics[RefRpsIdx]; ++j) {
00960             uint32_t kdx = m_activeSPS->m_numNegativePics[RefRpsIdx] + j;
00961             int32_t dpoc = m_activeSPS->m_DeltaPocS1[RefRpsIdx][j] + deltaRps;
00962             if (dpoc > 0 && use_delta_flag[kdx]) {
00963                 m_activeSPS->m_DeltaPocS1[idx][u] = dpoc;
00964                 m_activeSPS->m_UsedByCurrPicS1[idx][u] = m_activeSPS->m_used_by_curr_pic_flag[kdx];
00965                 u++;
00966             }
00967         }
00968         m_activeSPS->m_numPositivePics[idx] = u;
00969         m_activeSPS->m_NumDeltaPocs[idx] = m_activeSPS->m_numNegativePics[idx] + m_activeSPS->m_numPositivePics[idx];
00970         // REPORT("@@@@ %4d @@@@ %4d @@@@ 1", idx, m_activeSPS->m_NumDeltaPocs[idx]);
00971     } else {
00972         // printf("ParseShortTermRefSet:[%d] (!bInterRefPicSetPrediction)\n", idx);
00973 
00974         uint32_t numNegativePics = ReadUE(); // num_negative_pics
00975         // REPORT("%-40s - %8d", "num_negative_pics", numNegativePics);
00976         uint32_t numPositivePics = ReadUE(); // num_positive_pics
00977         // REPORT("%-40s - %8d", "num_positive_pics", numPositivePics);
00978 
00979         // Used to assist validation of implementation
00980         uint32_t deltaPosMinus1;
00981         bool bUsedByCurrPic;
00982 
00983         for (uint32_t i = 0; i < numNegativePics; ++i) {
00984             deltaPosMinus1 = ReadUE(); // delta_poc_s0_minus1[i]
00985             // REPORT("%-40s - %8d", "delta_poc_s0_minus1", deltaPosMinus1);
00986             bUsedByCurrPic = ReadFlag(); // used_by_curr_pic_s0_flag[i]
00987             // REPORT("%-40s - %8d", "used_by_curr_pic_s0_flag", bUsedByCurrPic);
00988             m_activeSPS->m_UsedByCurrPicS0[idx][i] = bUsedByCurrPic;
00989             if (i == 0)
00990                 m_activeSPS->m_DeltaPocS0[idx][i] = -(int32_t)(deltaPosMinus1 + 1);
00991             else
00992                 m_activeSPS->m_DeltaPocS0[idx][i] = m_activeSPS->m_DeltaPocS0[idx][i - 1] - (deltaPosMinus1 + 1);
00993         }
00994 
00995         for (uint32_t i = 0; i < numPositivePics; ++i) {
00996             deltaPosMinus1 = ReadUE(); // delta_poc_s1_minus1[i]
00997             // REPORT("%-40s - %8d", "delta_poc_s1_minus1", deltaPosMinus1);
00998             bUsedByCurrPic = ReadFlag(); // used_by_curr_pic_s1_flag[i]
00999             // REPORT("%-40s - %8d", "used_by_curr_pic_s1_flag", bUsedByCurrPic);
01000             m_activeSPS->m_UsedByCurrPicS1[idx][i] = bUsedByCurrPic;
01001             if (i == 0)
01002                 m_activeSPS->m_DeltaPocS1[idx][i] = (deltaPosMinus1 + 1);
01003             else
01004                 m_activeSPS->m_DeltaPocS1[idx][i] = m_activeSPS->m_DeltaPocS1[idx][i - 1] + (deltaPosMinus1 + 1);
01005         }
01006         m_activeSPS->m_numNegativePics[idx] = numNegativePics;
01007         m_activeSPS->m_numPositivePics[idx] = numPositivePics;
01008         m_activeSPS->m_NumDeltaPocs[idx] = numNegativePics + numPositivePics;
01009         // REPORT("@@@@ %4d @@@@ %4d @@@@ 0", idx, m_activeSPS->m_NumDeltaPocs[idx]);
01010 
01011         //      printf("ParseShortTermRefSet:[%d] - m_numPositivePics = %d m_numNegativePics = %d\n", idx,
01012         //       m_activeSPS->m_numPositivePics[idx], m_activeSPS->m_numNegativePics[idx]);
01013     }
01014 
01015     return true;
01016 }
