01018 bool BaseDecoderHEVC::ParseRefPicListsModification() { return true; }
01019 
01020 bool BaseDecoderHEVC::ParsePredWeightTable() {
01021     bool bLumaWeightFlags[15] = {false};
01022     bool bChromaWeightFlags[15] = {false};
01023 
01024     uint32_t lumaLog2WeightDenom = ReadUE();
01025 
01026     if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
01027         ReadSE(); // delta_chroma_log2_weight_denom
01028     }
01029 
01030     for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL0ActiveMinus1; ++i) {
01031         bLumaWeightFlags[i] = ReadFlag(); // luma_weight_l0_flag[i]
01032     }
01033 
01034     if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
01035         for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL0ActiveMinus1; ++i) {
01036             bChromaWeightFlags[i] = ReadFlag(); // chroma_weight_l0_flag[i]
01037         }
01038     }
01039 
01040     for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL0ActiveMinus1; ++i) {
01041         if (bLumaWeightFlags[i]) {
01042             ReadSE(); // delta_luma_weight_l0[i]
01043             ReadSE(); // luma_offset_l0[i]
01044         }
01045 
01046         if (bChromaWeightFlags[i]) {
01047             for (uint32_t j = 0; j < 2; ++j) {
01048                 ReadSE(); // delta_chroma_weight_l0[i][j]
01049                 ReadSE(); // delta_chroma_offset_l0[i][j]
01050             }
01051         }
01052     }
01053 
01054     if (m_activeSlice.m_sliceType == SliceType::B) {
01055         memset(bLumaWeightFlags, 0, sizeof(bool) * 15);
01056         memset(bChromaWeightFlags, 0, sizeof(bool) * 15);
01057 
01058         for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL1ActiveMinus1; ++i) {
01059             bLumaWeightFlags[i] = ReadFlag();
01060         }
01061 
01062         if (m_activeSlice.m_sps->m_chromaArrayType != 0) {
01063             for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL1ActiveMinus1; ++i) {
01064                 bChromaWeightFlags[i] = ReadFlag();
01065             }
01066         }
01067 
01068         for (uint32_t i = 0; i <= m_activeSlice.m_numRefIDXL1ActiveMinus1; ++i) {
01069             if (bLumaWeightFlags[i]) {
01070                 ReadSE(); // delta_luma_weight_l1
01071                 ReadSE(); // luma_offset_l1
01072             }
01073 
01074             if (bChromaWeightFlags[i]) {
01075                 for (uint32_t j = 0; j < 2; ++j) {
01076                     ReadSE(); // delta_chroma_weight_l1[i][j]
01077                     ReadSE(); // delta_chroma_offset_l1[i][j]
01078                 }
01079             }
01080         }
01081     }
01082 
01083     return true;
01084 }
01085 
01086 bool BaseDecoderHEVC::HandleScalingList() {
01087     for (uint32_t sizeId = 0; sizeId < 4; ++sizeId) {
01088         uint32_t idx = ((sizeId == 3) ? 2 : 6);
01089         for (uint32_t matrixId = 0; matrixId < idx; matrixId++) {
01090             m_activeSPS->m_scaling_list_pred_mode_flag[sizeId][matrixId] = ReadFlag();
01091             if (!m_activeSPS->m_scaling_list_pred_mode_flag[sizeId][matrixId])
01092                 m_activeSPS->m_scaling_list_pred_matrix_id_delta[sizeId][matrixId] = ReadUE();
01093             else {
01094                 uint32_t nextCoef = 8;
01095                 uint8_t coefNum = (64 > (1 << (4 + (sizeId << 1)))) ? (1 << (4 + (sizeId << 1))) : 64; // min function
01096                 if (sizeId > 1) {
01097                     m_activeSPS->m_scaling_list_dc_coef_minus8[sizeId - 2][matrixId] = ReadSE();
01098                     nextCoef = m_activeSPS->m_scaling_list_dc_coef_minus8[sizeId - 2][matrixId] + 8;
01099                 }
01100                 for (int i = 0; i < coefNum; ++i) {
01101                     m_activeSPS->m_scaling_list_delta_coef = ReadSE();
01102                     nextCoef = (nextCoef + m_activeSPS->m_scaling_list_delta_coef + 256) % 256;
01103                     m_activeSPS->m_ScalingList[sizeId][matrixId][i] = nextCoef;
01104                 }
01105             }
01106         }
01107     }
01108 
01109     return true;
01110 }
